draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  // dog body
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  // dog head
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2 - 30, 15, 0, 2 * Math.PI);
  ctx.stroke();
  // ears
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50 - 10, H/2 - 40);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - 20, H/2 - 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50 + 10, H/2 - 40);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + 20, H/2 - 60);
  ctx.stroke();
  // legs
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - 20, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + 20, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - 10, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + 10, H/2 + 50);
  ctx.stroke();
  // tail
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 30);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + Math.cos(t) * 20, H/2 + 60);
  ctx.stroke();
  ctx.restore();
}
